$bp=$pdo->prepare('SELECT enabled,fallback_message,handoff_rules_json,business_hours_json FROM bot_profiles WHERE tenant_id=?');$bp->execute([$tid]);$bot=$bp->fetch();$reply=null;$handoff=false;if($bot&&(int)$bot['enabled']===1){$norm=mb_strtolower($body);$settings=json_decode($bot['handoff_rules_json']??'{}',true)?:[];$handoffWords=array_values(array_filter(array_map('trim',explode(',',mb_strtolower($settings['handoff_keywords']??'agente, asesor, persona, humano, representante')))));$askedHuman=false;foreach($handoffWords as $kw){if($kw!==''&&mb_strpos($norm,$kw)!==false){$askedHuman=true;break;}}if($askedHuman){$handoff=true;$hours=json_decode($bot['business_hours_json']??'{}',true)?:[];$inHours=true;if(!empty($hours['enabled'])){$now=new DateTimeImmutable('now');$day=(int)$now->format('N');$hm=$now->format('H:i');$days=array_map('intval',$hours['days']??[]);$inHours=in_array($day,$days,true)&&$hm>=($hours['start']??'08:00')&&$hm<=($hours['end']??'17:00');$today=$now->format('Y-m-d');foreach(($hours['special_dates']??[]) as $special){if(($special['date']??'')!==$today)continue;if(($special['type']??'closed')==='closed'){$inHours=false;}else{$ss=$special['start']??'';$se=$special['end']??'';$inHours=$ss!==''&&$se!==''&&$hm>=$ss&&$hm<=$se;}break;}}$reply=$inHours?'Claro. Voy a transferirte con un agente de '.$w['company'].'.':($hours['outside_message']??'En este momento estamos fuera del horario de atención. Dejé tu conversación pendiente para que un agente continúe contigo.');}else{$rq=$pdo->prepare('SELECT name,keywords,response FROM nivo_rules WHERE tenant_id=? AND active=1 ORDER BY priority,id');$rq->execute([$tid]);foreach($rq->fetchAll() as $r){foreach(array_filter(array_map('trim',explode(',',mb_strtolower($r['keywords'])))) as $kw)if($kw!==''&&mb_strpos($norm,$kw)!==false){$reply=$r['response'];break 2;}}if($reply===null){$words=array_values(array_unique(array_filter(preg_split('/[^\p{L}\p{N}]+/u',$norm),fn($x)=>mb_strlen($x)>=3)));$q=$pdo->prepare("SELECT n